#!/usr/bin/env python3
"""Install the reviewed trust-core coverage tests and governed scope."""
from __future__ import annotations

import base64
import gzip
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEST = ROOT / "skills/tsao-dft-hpc-provenance/tests/test_trust_core_coverage.py"
PAYLOAD = """"""


def main() -> None:
    TEST.write_bytes(gzip.decompress(base64.b64decode(PAYLOAD)))
    path = ROOT / "scripts/run_coverage.py"
    text = path.read_text(encoding="utf-8")
    anchor = ')\n\n\ndef percent'
    if "GOVERNED_PRODUCTION" not in text:
        text = text.replace(anchor, ')\nGOVERNED_PRODUCTION = frozenset(TRUST_CORE)\n\n\ndef percent', 1)
    loop_anchor = '            except ValueError:\n                continue\n            analysis = coverage._analyze(filename)\n'
    if "relative not in GOVERNED_PRODUCTION" not in text:
        text = text.replace(loop_anchor, '            except ValueError:\n                continue\n            if relative not in GOVERNED_PRODUCTION:\n                continue\n            analysis = coverage._analyze(filename)\n', 1)
    payload_anchor = '            "trust_core": {path: per_file.get(path) for path in TRUST_CORE},\n            "per_file": per_file,\n'
    if '"governed_production"' not in text:
        text = text.replace(payload_anchor, '            "governed_production": sorted(GOVERNED_PRODUCTION),\n            "trust_core": {path: per_file.get(path) for path in TRUST_CORE},\n            "per_file": per_file,\n', 1)
    path.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
